const item = $input.first();

const data = item.json || {};


// =============================================
// HELPER — NORMALIZE FIELD NAMES
// =============================================

const normalizeKey = (key) =>
  String(key)
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');


// =============================================
// FIND JSON FIELD
// =============================================

const getJsonValue = (...possibleNames) => {

  const normalizedNames =
    possibleNames.map(normalizeKey);

  for (const [key, value] of Object.entries(data)) {

    if (
      normalizedNames.includes(
        normalizeKey(key)
      )
    ) {
      return String(value ?? '').trim();
    }

  }

  return '';
};


// =============================================
// GET FORM VALUES
// =============================================

const facultyUrl = getJsonValue(
  'faculty_url',
  'Faculty / Department URL',
  'Faculty Department URL',
  'Faculty_URL',
  'Department_URL'
);

const targetField = getJsonValue(
  'target_field',
  'Target Field',
  'Target_Field'
);

const degreeLevel = getJsonValue(
  'degree_level',
  'Degree Level',
  'Degree_Level'
);

const cvUrl = getJsonValue(
  'upload_cv',
  'Upload CV',
  'CV',
  'CV File'
);

const motivationLetterUrl = getJsonValue(
  'upload_motivation_letter',
  'Upload Motivation Letter',
  'Motivation Letter',
  'Motivation Letter File'
);


// =============================================
// VALIDATION
// =============================================

const studentEmail = getJsonValue('Email', 'Email Address', 'Student Email');
if (!/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(studentEmail)) {
  throw new Error('A single valid student Email is required.');
}
item.json.student_email = studentEmail;

if (!facultyUrl) {
  throw new Error(
    'Faculty / Department URL is required.'
  );
}

if (!/^https?:\/\/.+/i.test(facultyUrl)) {
  throw new Error(
    'Faculty / Department URL is invalid.'
  );
}

if (!targetField) {
  throw new Error(
    'Target Field is required.'
  );
}

if (!degreeLevel) {
  throw new Error(
    'Degree Level is required.'
  );
}

if (!cvUrl) {
  throw new Error(
    'CV Google Drive URL is missing.'
  );
}

if (!motivationLetterUrl) {
  throw new Error(
    'Motivation Letter Google Drive URL is missing.'
  );
}


// =============================================
// CREATE CLEAN STANDARD FIELDS
// =============================================

item.json.faculty_url = facultyUrl;
item.json.target_field = targetField;
item.json.degree_level = degreeLevel;

item.json.cv_url = cvUrl;
item.json.motivation_letter_url =
  motivationLetterUrl;


// =============================================
// RETURN
// =============================================

return [item];

const agentItem = $input.first();
const agentData = agentItem.json || {};

const originalInput =
  $('02 — Validate & Normalize Input').first().json;


// =============================================
// GET STRUCTURED STUDENT PROFILE
// =============================================

let profile =
  agentData.output ??
  agentData.response?.output ??
  agentData;


// =============================================
// HANDLE STRING JSON IF NEEDED
// =============================================

if (typeof profile === 'string') {

  const cleaned = profile
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  try {
    profile = JSON.parse(cleaned);
  } catch {
    throw new Error(
      'Student Research Profile is not valid JSON.'
    );
  }
}


// =============================================
// BASIC VALIDATION
// =============================================

if (
  !profile ||
  typeof profile !== 'object'
) {
  throw new Error(
    'Student Research Profile is missing.'
  );
}

if (!originalInput.faculty_url) {
  throw new Error(
    'Faculty / Department URL is missing.'
  );
}

if (!originalInput.target_field) {
  throw new Error(
    'Target Field is missing.'
  );
}

if (!originalInput.degree_level) {
  throw new Error(
    'Degree Level is missing.'
  );
}


// =============================================
// FORCE MANUAL INPUT AS SOURCE OF TRUTH
// =============================================

profile.target_field =
  originalInput.target_field;

profile.degree_level =
  originalInput.degree_level;


// =============================================
// FINAL DISCOVERY CONTEXT
// =============================================

return [
  {
    json: {
      faculty_url:
        originalInput.faculty_url,

      target_field:
        originalInput.target_field,

      degree_level:
        originalInput.degree_level,

      student_profile: profile
    }
  }
];

const item = $input.first();


// =============================================
// GET PROFESSORS
// =============================================

const professors =
  item.json?.output?.professors ?? [];

if (!Array.isArray(professors)) {
  throw new Error(
    'Professor array not found at output.professors.'
  );
}

if (professors.length === 0) {
  return [{ json: { candidate_found: false, status: 'NO_CANDIDATES', message: 'No professor candidates were found in the supplied directory.' } }];
}


// =============================================
// GET ORIGINAL CONTEXT
// =============================================

const context =
  $('07 — Prepare Professor Discovery Context')
    .first()
    .json;

const facultyUrl =
  String(context.faculty_url || '')
    .trim();


// =============================================
// URL NORMALIZER
// =============================================

function normalizeUrl(rawUrl, baseUrl) {

  let raw =
    String(rawUrl || '')
      .trim();

  if (!raw) {
    return '';
  }


  // Already absolute
  if (/^https?:\/\//i.test(raw)) {

    return raw
      .split('#')[0]
      .trim();
  }


  // Protocol-relative URL
  if (raw.startsWith('//')) {

    const protocol =
      baseUrl.startsWith('https://')
        ? 'https:'
        : 'http:';

    return protocol + raw;
  }


  // Get domain root from faculty URL
  const rootMatch =
    baseUrl.match(
      /^(https?:\/\/[^/]+)/i
    );

  if (!rootMatch) {
    return '';
  }

  const root =
    rootMatch[1];


  // Root-relative URL
  if (raw.startsWith('/')) {

    return (
      root +
      raw
    )
      .split('#')[0];
  }


  // Relative URL
  const cleanBase =
    baseUrl
      .split('#')[0]
      .split('?')[0];

  const lastSlash =
    cleanBase.lastIndexOf('/');

  const directory =
    lastSlash >= 0
      ? cleanBase.substring(
          0,
          lastSlash + 1
        )
      : cleanBase + '/';

  return (
    directory +
    raw.replace(/^\.\//, '')
  )
    .split('#')[0];
}


// =============================================
// PROCESS PROFESSORS
// =============================================

const seen = new Set();

const output = [];

for (const professor of professors) {

  const name =
    String(
      professor.name || ''
    ).trim();

  const rawUrl =
    String(
      professor.profile_url || ''
    ).trim();


  if (!name || !rawUrl) {
    continue;
  }


  const profileUrl =
    normalizeUrl(
      rawUrl,
      facultyUrl
    );


  if (!profileUrl) {
    continue;
  }


  // ===========================================
  // BASIC URL VALIDATION
  // ===========================================

  if (
    !/^https?:\/\//i.test(profileUrl)
  ) {
    continue;
  }


  // ===========================================
  // REMOVE EXTERNAL PROFILE / SOCIAL LINKS
  // ===========================================

  const lowerUrl =
    profileUrl.toLowerCase();

  const blockedDomains = [
    'linkedin.com',
    'facebook.com',
    'instagram.com',
    'twitter.com',
    'x.com/',
    'researchgate.net',
    'orcid.org'
  ];

  if (
    blockedDomains.some(
      domain =>
        lowerUrl.includes(domain)
    )
  ) {
    continue;
  }


  // ===========================================
  // DUPLICATE CHECK
  // ===========================================

  const duplicateKey =
    profileUrl
      .toLowerCase()
      .replace(/\/$/, '');

  if (seen.has(duplicateKey)) {
    continue;
  }

  seen.add(duplicateKey);


  // ===========================================
  // RELEVANCE
  // ===========================================

  const rawRelevance =
    String(
      professor.field_relevance_hint || ''
    )
      .trim()
      .toUpperCase();

  const relevance =
    ['HIGH', 'MEDIUM', 'UNKNOWN']
      .includes(rawRelevance)
      ? rawRelevance
      : 'UNKNOWN';


  // ===========================================
  // FINAL PROFESSOR ITEM
  // ===========================================

  output.push({

    json: {

      candidate_found: true,

      professor_name:
        name,

      designation:
        String(
          professor.designation || ''
        ).trim(),

      department:
        String(
          professor.department || ''
        ).trim(),

      professor_profile_url:
        profileUrl,

      field_relevance_hint:
        relevance,

      source_evidence:
        String(
          professor.source_evidence || ''
        ).trim(),

      faculty_url:
        facultyUrl,

      target_field:
        context.target_field,

      degree_level:
        context.degree_level,

      student_profile:
        context.student_profile

    }

  });

}


// =============================================
// FINAL VALIDATION
// =============================================

if (output.length === 0) {

  return [{ json: { candidate_found: false, status: 'NO_USABLE_PROFILE_URLS', message: 'No usable professor profile URLs were found.' } }];

}


return output;

const prepared =
  $('13 — Prepare Professor Analysis Input')
    .item
    ?.json || {};

const data = $json.output ?? $json;

const num = (value, min, max) => {
  const n = Number(value);

  if (!Number.isFinite(n)) {
    return 0;
  }

  return Math.max(
    min,
    Math.min(max, Math.round(n))
  );
};


// =============================================
// VALIDATE SCORE COMPONENTS
// =============================================

const researchFieldMatch =
  num(data.research_field_match, 0, 40);

const studentSkillsMatch =
  num(data.student_skills_match, 0, 20);

const researchInterestMatch =
  num(data.research_interest_match, 0, 20);

const academicBackgroundMatch =
  num(data.academic_background_match, 0, 10);

const supervisionRelevance =
  num(data.supervision_relevance, 0, 10);


// =============================================
// CALCULATE SCORE OURSELVES
// =============================================

const overallScore =
  researchFieldMatch +
  studentSkillsMatch +
  researchInterestMatch +
  academicBackgroundMatch +
  supervisionRelevance;


// =============================================
// PRIORITY
// =============================================

let recommendation;

if (overallScore >= 80) {
  recommendation = 'HIGH_PRIORITY';
}
else if (overallScore >= 65) {
  recommendation = 'STRONG_MATCH';
}
else if (overallScore >= 50) {
  recommendation = 'POSSIBLE_MATCH';
}
else {
  recommendation = 'LOW_MATCH';
}


// =============================================
// FINAL CLEAN RECORD
// =============================================

return {
  json: {
    professor_name:
      String(data.professor_name || '').trim(),

    designation:
      String(data.designation || '').trim(),

    department:
      String(data.department || '').trim(),

    email:
      String(prepared.detected_email || 'NOT_FOUND').trim(),

    professor_profile_url:
      String(
        prepared.professor_profile_url ||
        $('11 — Professor Candidates Found?')
          .item.json.professor_profile_url ||
        ''
      ).trim(),

    research_interests:
      Array.isArray(data.research_interests)
        ? data.research_interests
        : [],

    research_topics:
      Array.isArray(data.research_topics)
        ? data.research_topics
        : [],

    relevant_research_evidence:
      Array.isArray(data.relevant_research_evidence)
        ? data.relevant_research_evidence
        : [],

    supervision_status:
      String(
        data.supervision_status || 'UNKNOWN'
      ).trim(),

    research_field_match:
      researchFieldMatch,

    student_skills_match:
      studentSkillsMatch,

    research_interest_match:
      researchInterestMatch,

    academic_background_match:
      academicBackgroundMatch,

    supervision_relevance:
      supervisionRelevance,

    overall_score:
      overallScore,

    match_reason:
      String(data.match_reason || '').trim(),

    recommendation
  }
};

const items = $input.all();


// =============================================
// COLLECT VALID PROFESSORS
// =============================================

const professors = items
  .map(item => item.json)
  .filter(professor => {

    return (
      professor.professor_name &&
      professor.professor_profile_url &&
      Number.isFinite(
        Number(professor.overall_score)
      )
    );

  });


// =============================================
// SORT HIGHEST SCORE FIRST
// =============================================

professors.sort((a, b) => {

  return (
    Number(b.overall_score) -
    Number(a.overall_score)
  );

});


// =============================================
// SELECT TOP 6
// =============================================

const topProfessors =
  professors.slice(0, 6);


// =============================================
// ADD RANK
// =============================================

return topProfessors.map(
  (professor, index) => ({
    json: {
      rank: index + 1,
      ...professor
    }
  })
);

// One file for this execution only. The shared results sheet is never exported.
const rows = $('16 — Prepare Professor Sheet Records').all().map(item => item.json);
if (rows.length === 0) return [];
const headers = ['rank','professor_name','designation','department','email','professor_profile_url','research_interests','research_topics','relevant_research_evidence','research_fit_score','match_reason','recommendation','supervision_status'];
const cell = value => {
  let text = String(value ?? '');
  // Prevent spreadsheet formula injection when a CSV is opened.
  if (/^[\s\u0000-\u001f]*[=+@-]/.test(text)) text = "'" + text;
  return '"' + text.replace(/"/g, '""') + '"';
};
const csv = '\uFEFF' + [headers.map(cell).join(','), ...rows.map(row => headers.map(key => cell(row[key])).join(','))].join('\r\n');
const data = await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), 'professor-matches.csv', 'text/csv');
return [{ json: { result_count: rows.length }, binary: { data } }];
